#include <iostream>
using namespace std;

class A_Queue {
private:
    char cArray[10];
    int size = 10;
    int front = 0;
    int back = 0;
    int numElements = 0;
public:
    bool isFull() {
        return numElements == size;
    }
    bool isEmpty() {
        return numElements == 0;
    }
    void enqueue(char c) {
        if (isFull()) {
            cout << "Queue is full" << endl;
            return;
        }
        cArray[back] = c;
        back = (++back) % size;
        numElements++;
    }
    char dequeue() {
        if (isEmpty()) {
            cout << "Queue is empty" << endl;
            return ' ';
        }
        char c = cArray[front];
        front = (++front) % size;
        numElements--;
        return c;
    }
};

int main() {
    A_Queue q;
    for (char c = 'A'; c <= 'J'; c++) {
        q.enqueue(c);
    }
    q.enqueue('X');
    cout << "Out: " << q.dequeue() << endl;
    cout << "Out: " << q.dequeue() << endl;
    q.enqueue('K');
    return 0;
}
